# What each ticket event does in Zammad, as its Checkmk integration did for zammad-bridge:
# a failure with no open ticket of its host and service opens one; with one, adds a note;
# a recovery (OK or UP) closes the open ones with a note; a recovery with none open is nothing.
# An event with repeat "skip" (Dockhand's kill, whose die follows) adds no note to an open one.
# Input: one item from "Gather": events (every event of this run: host, service, state,
# text, source) and tickets (Zammad's open tickets, a full response). Output: one item per
# write: method, path, body, what the read-back must show, and the event's source. A failed
# ticket list stops the run here (no write on an unknown state).
GROUP = "Alerts"
CUSTOMER_ID = 1  # Zammad's system user "-", as the Checkmk endpoint uses

g = _items[0]["json"] if _items else {}
events = g.get("events") or []
response = g.get("tickets") or {}
if "error" in response or "body" not in response:
    raise Exception("Zammad's open tickets couldn't be listed; nothing written")
found = response["body"]
found = found.get("tickets") if isinstance(found, dict) else found
found = [t for t in found if isinstance(t, dict)] if isinstance(found, list) else []


def key(ticket):
    prefs = ticket.get("preferences") or {}
    ck = prefs.get("check_mk") or prefs.get("checkmk") or {}
    return str(ck.get("host") or ""), str(ck.get("service") or "")


out = []
created = set()  # keys this run opens a ticket for: a second event of one adds nothing
for event in events:
    host, service, state = str(event.get("host") or ""), str(event.get("service") or ""), str(event.get("state") or "")
    text = str(event.get("text") or "")
    title = host + " is " + state
    article = {"subject": title, "body": text or title, "type": "web", "sender": "Customer",
               "internal": False, "content_type": "text/plain"}
    mine = [t for t in found if key(t) == (host, service)]
    common = {"host": host, "service": service, "state": state, "source": event.get("source")}
    if state.upper() in ("OK", "UP"):
        for t in mine:
            out.append(dict(common, action="close", method="PUT", path="/api/v1/tickets/" + str(t["id"]),
                            body={"state": "closed", "article": article},
                            ticket=t["id"], number=t.get("number"), expect="closed"))
        if not mine:
            print(title + ": no open ticket, nothing to close")
    elif mine and event.get("repeat") == "skip":
        print(title + ": already open (#" + ", #".join(str(t.get("number")) for t in mine) + "), nothing added")
    elif mine:
        for t in mine:
            out.append(dict(common, action="note", method="POST", path="/api/v1/ticket_articles",
                            body=dict(article, ticket_id=t["id"]),
                            ticket=t["id"], number=t.get("number"), expect="open"))
    elif (host, service) in created:
        print(title + ": opened earlier in this run, nothing added")
    else:
        created.add((host, service))
        out.append(dict(common, action="create", method="POST", path="/api/v1/tickets",
                        body={"title": title[:250], "group": GROUP, "customer_id": CUSTOMER_ID,
                              "preferences": {"check_mk": {"host": host, "service": service}},
                              "article": article},
                        ticket=None, number=None, expect="open"))
for o in out:
    print(o["action"] + " " + o["host"] + " is " + o["state"] + (" #" + str(o["number"]) if o["number"] else ""))
return [{"json": o} for o in out]

# Each write read back: Zammad must show the ticket with this event's key and the state the
# write meant (closed after a close; new or open after a create or a note), or the run fails.
# Input: one item per write from "Gather the write": decision, back (the ticket read back,
# a full response).
out, problems = [], []
for item in _items:
    g = item["json"]
    d = g.get("decision") or {}
    back = g.get("back") or {}
    what = str(d.get("action", "?")) + " " + str(d.get("host"))
    if "error" in back or not isinstance(back.get("body"), dict):
        problems.append(what + ": Zammad couldn't be read back")
        continue
    t = back["body"]
    ck = (t.get("preferences") or {}).get("check_mk") or {}
    state = str(t.get("state") or "")
    wrong = []
    if (ck.get("host"), ck.get("service")) != (d.get("host"), d.get("service")):
        wrong.append("its key reads " + repr((ck.get("host"), ck.get("service"))))
    if (d.get("expect") == "closed") != (state == "closed"):
        wrong.append("its state reads " + repr(state))
    if wrong:
        problems.append(what + " #" + str(t.get("number")) + " didn't take: " + "; ".join(wrong))
        continue
    print(str(d.get("action")) + " #" + str(t.get("number")) + ": read back " + state)
    out.append({"json": {"action": d.get("action"), "number": t.get("number"), "state": state,
                         "title": t.get("title")}})
if problems:
    raise Exception(" | ".join(problems))
return out

# Each alert as a ticket event: its text is the alert's summary and description, the members
# down (from "Prometheus: members down", for an alert with a query), its labels and its
# runbook, as zammad-bridge's to_checkmk wrote it. A failed member lookup says so: it isn't
# "none down". Input: one item per alert from "Gather the alert": alert, members (a full
# response, or an error).
LISTED = 25
# Labels left out of the ticket's text: Prometheus's own bookkeeping.
QUIET_LABELS = {"prometheus", "alertstate", "endpoint", "container", "uid"}


def describe(series):
    """One line per member: its pod or instance, its node, and its address."""
    lines = []
    for item in series:
        m = item.get("metric") or {}
        name = m.get("pod") or m.get("instance") or m.get("job") or "?"
        line = name
        if m.get("node"):
            line += " on " + m["node"]
        if m.get("instance") and m.get("instance") != name:
            line += " (" + m["instance"] + ")"
        lines.append(line)
    return sorted(set(lines))


def members(query, response):
    if not query:
        return []
    body = response.get("body") if isinstance(response, dict) and "error" not in response else None
    if not isinstance(body, dict) or body.get("status") != "success" or not isinstance(
            (body.get("data") or {}).get("result"), list):
        reason = (response.get("error") if isinstance(response, dict) else None) or (
            body.get("error") if isinstance(body, dict) else None) or "no answer"
        return ["Couldn't list which are down: Prometheus didn't answer (" + str(reason)[:120] + ")."]
    found = describe(body["data"]["result"])
    if not found:
        return ["Down now: none found (recovered since, or what's missing has no pod to list)."]
    more = ", the first " + str(LISTED) + " listed" if len(found) > LISTED else ""
    return ["Down now (" + str(len(found)) + more + "):"] + ["- " + line for line in found[:LISTED]]


out = []
for item in _items:
    a = item["json"].get("alert") or {}
    labels, notes = a.get("labels") or {}, a.get("annotations") or {}
    detail = [notes.get("summary", ""), notes.get("description", "")]
    detail += members(a.get("query"), item["json"].get("members"))
    detail += [k + "=" + str(v) for k, v in sorted(labels.items()) if k not in QUIET_LABELS]
    if notes.get("runbook_url"):
        detail.append("runbook: " + notes["runbook_url"])
    out.append({"json": {"source": "alertmanager", "host": a.get("host"), "service": a.get("service"),
                         "state": a.get("state"), "text": "\n".join(x for x in detail if x),
                         "repeat": "note", "hold": 0}})
return out
